begin;
insert into auth.users(id,email_confirmed_at) values ('76000000-0000-4000-8000-000000000001',now()),('76000000-0000-4000-8000-000000000002',now()),('76000000-0000-4000-8000-000000000003',null),('76000000-0000-4000-8000-000000000004',now());
insert into public.staff_roles(user_id,role) values ('76000000-0000-4000-8000-000000000002','admin'),('76000000-0000-4000-8000-000000000001','admin');
insert into public.talent_profiles(id,data,published) values ('submission-existing','{"name":"Existing","linkedinUrl":"https://www.linkedin.com/in/submission-existing"}',true),('submission-removed','{"name":"Removed","linkedinUrl":"https://www.linkedin.com/in/submission-removed"}',false);
insert into private.talent_suppressions(profile_id,linkedin_url) values ('submission-removed','https://www.linkedin.com/in/submission-removed');
create function pg_temp.check_true(value boolean,message text) returns void language plpgsql as $$ begin if value is distinct from true then raise exception 'Assertion failed: %',message; end if; end $$;
create function pg_temp.expect_error(query text,code text) returns void language plpgsql as $$ begin begin execute query; exception when others then if sqlstate=code then return; else raise; end if; end; raise exception 'Expected error %',code; end $$;
select pg_temp.check_true(private.talent_canonical_linkedin('https://in.linkedin.com/in/%53ubmission-Existing/?trk=one')='https://www.linkedin.com/in/submission-existing','canonical aliases and percent encoding');
select pg_temp.expect_error($q$select private.talent_canonical_linkedin('https://linkedin.com.evil.test/in/name')$q$,'22023');
select pg_temp.expect_error($q$select private.talent_canonical_linkedin('https://linkedin.com/in/foo%2Fbar')$q$,'22023');
select pg_temp.expect_error($q$insert into public.talent_profiles(id,data) values ('duplicate-variant','{"name":"Other","linkedinUrl":"https://in.linkedin.com/in/%73ubmission-existing"}')$q$,'23505');
set local role anon;
select pg_temp.expect_error('select public.talent_my_submissions()','42501');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','76000000-0000-4000-8000-000000000003',true);
select pg_temp.expect_error('select public.talent_my_submissions()','42501');
select set_config('request.jwt.claim.sub','76000000-0000-4000-8000-000000000001',true);
select pg_temp.check_true(public.talent_check_submission_identity('linkedin.com/in/submission-existing')->>'profile_id'='submission-existing','existing person routed to claim');
select pg_temp.check_true(public.talent_check_submission_identity('linkedin.com/in/submission-removed')='{"status":"unavailable"}'::jsonb,'suppression no private identity leak');
select pg_temp.expect_error($q$select public.talent_save_submission(null,null,'{"name":"Synthetic Engineer","linkedinUrl":"linkedin.com/in/new","email":"private@example.test"}','Private ownership proof details')$q$,'22023');
select set_config('request.jwt.claim.sub','76000000-0000-4000-8000-000000000004',true);
select public.talent_save_submission(null,null,'{"name":"","linkedinUrl":"linkedin.com/in/submission-new"}','');
select set_config('request.jwt.claim.sub','76000000-0000-4000-8000-000000000001',true);
select pg_temp.check_true(public.talent_check_submission_identity('linkedin.com/in/submission-new')->>'status'='available','unfinished draft cannot reserve identity');
select (public.talent_save_submission(null,null,'{"name":"Synthetic Engineer","title":"Firmware Engineer","location":"Bengaluru","linkedinUrl":"https://in.linkedin.com/in/submission-new/?source=test","education":"BTech","experience":"Firmware work","availability":"available"}','Private ownership proof details')->>'id') as sid \gset
select pg_temp.check_true(jsonb_array_length(public.talent_my_submissions())=1,'own draft visible');
select pg_temp.expect_error(format('select public.talent_submit_profile(%L,1,''Impersonator'',''2026-10-14-add-profile-v1'',true)',:'sid'),'22023');
select pg_temp.expect_error(format('select public.talent_submit_profile(%L,1,''Synthetic Engineer'',''2026-10-14-add-profile-v1'',false)',:'sid'),'22023');
select public.talent_submit_profile(:'sid',1,'Synthetic Engineer','2026-10-14-add-profile-v1',true);
select pg_temp.expect_error(format('select public.talent_save_submission(%L,1,''{"name":"Changed","linkedinUrl":"linkedin.com/in/submission-new"}'',''Private ownership proof details'')',:'sid'),'P0409');
select pg_temp.expect_error(format('select public.talent_review_submission(%L,1,''approved'',''Manual independent review done'')',:'sid'),'42501');
select set_config('request.jwt.claim.sub','76000000-0000-4000-8000-000000000004',true);
select pg_temp.check_true(jsonb_array_length(public.talent_my_submissions())=1 and public.talent_my_submissions()->0->'data'->>'name'='','other member sees only own incomplete draft');
select pg_temp.check_true(public.talent_check_submission_identity('linkedin.com/in/submission-new')='{"status":"unavailable"}'::jsonb,'private active identity hidden');
select pg_temp.expect_error('select public.talent_submission_queue()','42501');
select pg_temp.expect_error('select * from private.talent_submissions','42501');
select set_config('request.jwt.claim.sub','76000000-0000-4000-8000-000000000002',true);
select pg_temp.check_true(exists(select 1 from jsonb_array_elements(public.talent_submission_queue()) s where s->>'id'=:'sid' and s->'declaration'->>'signed_name'='Synthetic Engineer'),'review sees immutable declaration');
select public.talent_review_submission(:'sid',1,'changes_requested','Please clarify your current employment');
select set_config('request.jwt.claim.sub','76000000-0000-4000-8000-000000000001',true);
select public.talent_save_submission(:'sid',1,'{"name":"Synthetic Engineer","title":"Firmware Engineer","location":"Bengaluru","linkedinUrl":"linkedin.com/in/submission-new","education":"BTech","experience":"Firmware work"}','Updated private ownership evidence');
select public.talent_submit_profile(:'sid',2,'Synthetic Engineer','2026-10-14-add-profile-v1',true);
select set_config('request.jwt.claim.sub','76000000-0000-4000-8000-000000000002',true);
select pg_temp.expect_error(format('select public.talent_review_submission(%L,1,''approved'',''Manual independent review done'')',:'sid'),'P0409');
select public.talent_review_submission(:'sid',2,'approved','Manual independent identity and publication review done');
select pg_temp.check_true((select data->>'source'='member' and data->>'claimed'='true' and not data ?| array['email','phone','evidence','declaration','identityVerified','photoVersion'] from public.talent_profiles where id='member-'||:'sid'),'only approved public fields published, no extra verification or photo');
select set_config('request.jwt.claim.sub','76000000-0000-4000-8000-000000000001',true);
select pg_temp.check_true(public.talent_my_status('member-'||:'sid')->>'owner'='true','approved claimant owns profile');
select public.talent_update_profile('member-'||:'sid',1,'{"education":"Updated BTech","experience":"Updated work","availability":"available"}');
select pg_temp.expect_error($q$select public.talent_save_submission(null,null,'{"name":"Synthetic Engineer","linkedinUrl":"linkedin.com/in/another-person"}','Private ownership proof details')$q$,'P0409');
select public.talent_submit_request('submission-existing','claim','Private ownership evidence for existing profile',1,'Synthetic Engineer','2026-10-13-v1',true) as claim_id \gset
select set_config('request.jwt.claim.sub','76000000-0000-4000-8000-000000000002',true);
select pg_temp.expect_error(format('select public.talent_review_request(%L,''approved'',''Independent ownership review done'')',:'claim_id'),'P0409');
reset role;
select pg_temp.check_true((select count(*)=1 from private.talent_owners where user_id='76000000-0000-4000-8000-000000000001'),'claim cannot grant a second owned profile');
select pg_temp.check_true((select count(*)=2 from private.talent_submission_history where submission_id=:'sid' and event='submitted'),'both signed revisions retained');
select pg_temp.expect_error(format('update private.talent_submission_history set snapshot=''{}'' where submission_id=%L',:'sid'),'22023');
rollback;
